				$this->semValue = new Scalar\InterpolationNode($this->semStack[$pos - 2], new Expression\VariableNode(null, null, $this->semStack[$pos - 1], null), $this->semStack[$pos]);
				break;
			case 631:
				$this->semValue = new Scalar\InterpolationNode($this->semStack[$pos - 5], new Expression\ArrayAccessNode($this->semStack[$pos - 4], $this->semStack[$pos - 3], $this->semStack[$pos - 2], $this->semStack[$pos - 1]), $this->semStack[$pos]);
				break;
			case 633:
				$this->semValue = new Scalar\UnquotedStringNode($this->semStack[$pos]);
				break;
			case 634:
				$this->semValue = $this->offsetNumber($this->semStack[$pos]);
				break;
			case 635:
				$this->semValue = new Expression\UnaryOpNode($this->semStack[$pos - 1], new Scalar\IntegerNode($this->semStack[$pos]));
				break;
			default:
				$this->reduceDefault($rule, $pos);
		}
	}
}
